addpath('functions');

files = { ...
    'gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162331.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162934.offline.mi.mi_bhbf.gdf'};
N_GDFS = numel(files);

% loadRuns checks that every run has the same sample rate and the same
% channels in the same order, then concatenates EEG and shifts event positions
[s, h, sizes, hs] = loadRuns(files);
fs = h.SampleRate;
offsets = [0; cumsum(sizes(1:end-1))]; % samples before each run

for i = 1:N_GDFS %[output:group:8ed5987c]
    fprintf('Run %d: %d samples (%.1f s), %d channels, %d events, fs = %d Hz\n', ... %[output:71b21e7f]
        i, sizes(i), sizes(i) / fs, numel(hs{i}.Label), numel(hs{i}.EVENT.POS), hs{i}.SampleRate); %[output:71b21e7f]
end %[output:group:8ed5987c]
% sample rate = 512 Hz, 17 channels
% sizes = 172032, 162816, 165888
%%
lbl = labelEvents(h, sizes);
Tk = lbl.Tk;
Rk = lbl.Rk;
%%
t = (1:size(s, 1)) ./ fs;

figure; %[output:2b9de220]
ax = subplot(2, 1, 1); %[output:2b9de220]
hold(ax, 'on'); %[output:2b9de220]
plot(ax, t, Tk, 'DisplayName', 'Tk'); %[output:2b9de220]
plot(ax, t, Rk, 'DisplayName', 'Rk'); %[output:2b9de220]
hold(ax, 'off'); %[output:2b9de220]
xlabel(ax, 'seconds [s]'); %[output:2b9de220]
legend(ax, 'show'); %[output:2b9de220]

ax = subplot(2, 1, 2); %[output:2b9de220]
hold(ax, 'on'); %[output:2b9de220]
plot(ax, t, lbl.Fk, 'DisplayName', 'Fk'); %[output:2b9de220]
plot(ax, t, lbl.Ak, 'DisplayName', 'Ak'); %[output:2b9de220]
plot(ax, t, lbl.CFk, 'DisplayName', 'CFk'); %[output:2b9de220]
plot(ax, t, lbl.Xk, 'DisplayName', 'Xk'); %[output:2b9de220]
hold(ax, 'off'); %[output:2b9de220]
xlabel(ax, 'seconds [s]'); %[output:2b9de220]
legend(ax, 'show'); %[output:2b9de220]
%%
% Validation of the concatenated dataset
total_size = 0;
for i = 1:N_GDFS
    total_size = total_size + size(hs{i}.EVENT.POS, 1);
end
assert(size(s, 1) == sum(sizes));
assert(size(h.EVENT.POS, 1) == total_size);

first = 1;
for i = 1:N_GDFS
    evIdx = first:first + numel(hs{i}.EVENT.POS) - 1;
    first = evIdx(end) + 1;

    % positions shifted by the samples of all preceding runs
    assert(isequal(h.EVENT.POS(evIdx), hs{i}.EVENT.POS + offsets(i)));
    assert(isequal(h.EVENT.TYP(evIdx), hs{i}.EVENT.TYP));
    assert(isequal(h.EVENT.DUR(evIdx), hs{i}.EVENT.DUR));

    % Rk identifies all (and only) the samples of this run
    assert(all(Rk(offsets(i)+1:offsets(i)+sizes(i)) == i));
    assert(nnz(Rk == i) == sizes(i));

    % trial numbering restarts from one and has no gaps
    trialNums = unique(Tk(Rk == i & Tk > 0));
    assert(isequal(trialNums', 1:numel(trialNums)));

    % same number of trials as trial-start events in the original file
    assert(numel(trialNums) == nnz(hs{i}.EVENT.TYP == 1));
end
fprintf('Validation OK\n'); %[output:90a9ee9e]
%%
% Events across the junction between run 1 and run 2: the combined time axis
% just puts the runs next to each other (the real pause between runs is lost)
JUNCTION = sizes(1) / fs;
START_PLOT = floor(JUNCTION) - 10;
END_PLOT = floor(JUNCTION) + 10;

interval = START_PLOT*fs:END_PLOT*fs;
x = interval ./ fs;

figure('Position', [100 100 1000 1000]); %[output:7a94cad0]

for i = 1:3 %[output:group:38a7b8f5]
    ax = subplot(3, 1, i); %[output:7a94cad0]
    plotEvents(ax, h, fs, [START_PLOT END_PLOT], [-80 80]);
    plot(ax, x, s(interval, i), 'b', 'HandleVisibility', 'off');
    xline(ax, JUNCTION, 'r--', 'LineWidth', 2, 'HandleVisibility', 'off');
    title(ax, sprintf("EEG Channel #%d in [%d,%d]s (run 1 | run 2)", i, START_PLOT, END_PLOT));
    xlabel(ax, 'seconds [s]');
    ylabel(ax, 'Amplitude [uV]');
    hold(ax, 'off');
end %[output:group:38a7b8f5]
%%
% Trials selected with BOTH Tk and Rk. Event durations jitter by a few
% samples (<= 10 ms), so lengths go from 4589 to 4593: keep the shortest,
% trimming the END of the longer ones.
[Trials, Ck, RunTrial, info] = extractTrials(s(:, 1:16), lbl, MaxLengthDiff=5);

fprintf('Trials: %s [samples x channels x trials]\n', mat2str(size(Trials))); %[output:1ad782eb]
fprintf('Trial length: %d..%d samples -> kept %d\n', info.minLength, info.maxLength, size(Trials, 1)); %[output:659850d3]

% Cue and run of every stored trial must match the labels at its start
for j = 1:size(Trials, 3)
    trialIdx = info.start(j):info.start(j) + size(Trials, 1) - 1;
    assert(all(Rk(trialIdx) == RunTrial(j)));
    cuesInTrial = unique(lbl.Ak(trialIdx));
    assert(isequal(cuesInTrial(cuesInTrial > 0), Ck(j)));
end

cues = unique(Ck);
countTable = zeros(N_GDFS, numel(cues));
for i = 1:N_GDFS
    for c = 1:numel(cues)
        countTable(i, c) = nnz(RunTrial == i & Ck == cues(c));
    end
end
disp(array2table(countTable, ... %[output:group:80936800] %[output:592cc794]
    'VariableNames', compose('Cue_%d', cues'), ... %[output:592cc794]
    'RowNames', compose('Run_%d', (1:N_GDFS)'))); %[output:group:80936800] %[output:592cc794]
% No trials excluded
%%
channel = 7; % C3
t = (0:size(Trials, 1)-1) ./ fs; % time from trial start

[avg, counts] = cueAverage(Trials, Ck, cues);

figure('Position', [100 100 1000 800]); %[output:6b98c400]
ax = gobjects(numel(cues), 1);
for c = 1:numel(cues)
    v = find(Ck == cues(c));
    ax(c) = subplot(numel(cues), 1, c); %[output:6b98c400]
    hold(ax(c), 'on');
    plot(ax(c), t, Trials(:, channel, v(1)), 'DisplayName', ...
        sprintf('Trial #%d (run %d, trial %d)', v(1), RunTrial(v(1)), info.trialInRun(v(1))));
    plot(ax(c), t, avg(:, channel, c), 'LineWidth', 1.5, 'DisplayName', ...
        sprintf('Mean (%d trials)', counts(c)));
    hold(ax(c), 'off');
    title(ax(c), sprintf('Cue %d - Channel %d', cues(c), channel));
    xlabel(ax(c), 'time from trial start [s]');
    ylabel(ax(c), 'Amplitude [uV]');
    legend(ax(c), 'show', 'Location', 'best');
    xlim(ax(c), [0, t(end)]);
end
linkaxes(ax, 'y'); % common amplitude scale %[output:6b98c400]
%%
figure; %[output:6162d6ae]
ax = subplot(1, 1, 1); %[output:6162d6ae]
hold(ax, 'on'); %[output:6162d6ae]
for c = 1:numel(cues)
    plot(ax, t, avg(:, channel, c), 'DisplayName', sprintf('Cue %d (%d trials)', cues(c), counts(c))); %[output:6162d6ae]
end
hold(ax, 'off'); %[output:6162d6ae]
title(ax, sprintf('Grand average Cue 771 vs 773 on Channel %d (all runs)', channel)); %[output:6162d6ae]
xlabel(ax, 'time from trial start [s]'); %[output:6162d6ae]
ylabel(ax, 'Amplitude [uV]'); %[output:6162d6ae]
legend(ax, 'show'); %[output:6162d6ae]
xlim(ax, [0, t(end)]); %[output:6162d6ae]
% Averaging raw EEG removes what is not time-locked: it does not show
% differences in MI rhythms between the two cues (-> band power, Lab04)

